1        llvm::Optional<uint32_t> JSLexer::consumeBracedCodePoint(bool errorOnFail) {
       2          assert(*curCharPtr_ == '{' && "braced codepoint must begin with {");
       3          ++curCharPtr_;
       4          const char *start = curCharPtr_;
       5
       6          // Set to true if we failed to get a code point that is in bounds or saw
       7          // an invalid character.
       8          bool failed = false;
       9
      10          // Loop until we hit the } or eof, max out the value, or see an invalid char.
      11          uint32_t cp = 0;
      12          for (; *curCharPtr_ != '}'; ++curCharPtr_) {
      13            int ch = *curCharPtr_;
      14            if (ch >= '0' && ch <= '9') {
      15              ch -= '0';
      16            } else if (ch >= 'a' && ch <= 'f') {
      17              ch -= 'a' - 10;
      18            } else if (ch >= 'A' && ch <= 'F') {
      19              ch -= 'A' - 10;
      20            } else {
      21              // The only way this can be the end of the buffer is if this is a \0.
      22              // Check if this is the end of the buffer, else continue so that we
      23              // may report more errors after this braced code point.
      24              if (curCharPtr_ == bufferEnd_) {
      25                if (!failed && errorOnFail) {
      26                  error(
      27                      SMLoc::getFromPointer(start),
      28                      "non-terminated unicode codepoint escape");
      29                }
      30                return llvm::None;
      31              }
      32              // Invalid character, set the failed flag and continue.
      33              if (!failed && errorOnFail) {
      34                error(
      35                    SMLoc::getFromPointer(curCharPtr_),
      36                    "invalid character in unicode codepoint escape");
      37              }
      38              failed = true;
      39              continue;
      40            }
      41            cp = (cp << 4) + ch;
      42            if (cp > UNICODE_MAX_VALUE) {
      43              // Number grew too big, set the failed flag and continue.
      44              if (!failed && errorOnFail) {
      45                error(
      46                    SMLoc::getFromPointer(start),
      47                    "unicode codepoint escape is too large");
      48              }
      49              failed = true;
      50            }
      51          }
      52
      53          assert(curCharPtr_ < bufferEnd_ && "bufferEnd_ should cause early return");
      54
      55          // An empty escape sequence is invalid.
      56          if (curCharPtr_ == start) {
      57            if (!failed && errorOnFail) {
      58              error(SMLoc::getFromPointer(start), "empty unicode codepoint escape");
      59            }
      60            failed = true;
      61          }
      62
      63          // Consume the final } and return.
      64          ++curCharPtr_;
      65          return failed ? llvm::None : llvm::Optional<uint32_t>{cp};
      66        }
